do $Q$ declare d jsonb:=$J${"code":"ber","title":"Berlin \u00b7 A City Passport","country":"DE","country_name":"Germany","state":"Berlin","city":"Berlin","emblem":"\ud83d\udc3b","cover_bg":"1E2A44","paper":"F4F1EA","desc":"Berlin from the Brandenburg Gate to the Wall: the Reichstag dome and the Holocaust Memorial, Museum Island and the cathedral, the East Side Gallery and Checkpoint Charlie, Gendarmenmarkt and the TV Tower, the Kaiser Wilhelm Memorial Church and Charlottenburg Palace, a day in Potsdam, and four long-running Berlin food stops, plus two pages of laws, money and customs for visitors from the US.","tier":"150_500","note":"Expect roughly 150 to 220 euros a person (about $175 to $255), not counting the train to Potsdam, which a Berlin ABC ticket covers. The biggest costs are the TV Tower (from about 24.50 euros online), the Museum Island day ticket (24 euros), Charlottenburg Palace and Sanssouci. The Brandenburg Gate, the Reichstag dome, the Holocaust Memorial, the East Side Gallery, the Wall Memorial, the Topography of Terror and Glienicke Bridge are free. Book the Reichstag dome ahead; it is free but needs registration."}$J$; pg jsonb:=$J$[{"n":1,"type":"stamp","title":"The Gate & the Reichstag","ink":"5A6E8E","elements":[{"x":56,"y":100,"id":"086fbe80-cbbd-576a-a3e0-18b53807c5f1","runs":[{"text":"The Gate & the Reichstag"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":2,"type":"stamp","title":"Museum Island","ink":"6E6A86","elements":[{"x":56,"y":100,"id":"611e7760-442e-54ea-84a6-49baec802f83","runs":[{"text":"Museum Island"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":3,"type":"stamp","title":"The Wall & the Cold War","ink":"7A6A5A","elements":[{"x":56,"y":100,"id":"ceecd6e3-3169-5d5d-ac97-8ae4e1cbbc84","runs":[{"text":"The Wall & the Cold War"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":4,"type":"stamp","title":"Mitte Squares & the Tower","ink":"5A7A6E","elements":[{"x":56,"y":100,"id":"3f901d49-577d-5e63-93a6-c557973f3e76","runs":[{"text":"Mitte Squares & the Tower"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":5,"type":"stamp","title":"City West","ink":"8A6A4A","elements":[{"x":56,"y":100,"id":"f477592a-f97e-572e-84d0-04f1d6afc4c0","runs":[{"text":"City West"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":6,"type":"stamp","title":"Potsdam Day Trip","ink":"6E7A4A","elements":[{"x":56,"y":100,"id":"42fe4e85-0d62-523c-ab51-3147e48e8bc0","runs":[{"text":"Potsdam Day Trip"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":7,"type":"stamp","title":"Berlin Eats","ink":"8E4A44","elements":[{"x":56,"y":100,"id":"ff32d200-3bab-5b69-9d26-e18185f48245","runs":[{"text":"Berlin Eats"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":8,"type":"information","title":"Know Before You Go: Laws & Money","ink":"4E5A6E","elements":[{"x":56,"y":100,"id":"62074f0b-2f5f-54ae-959f-ffcc49c8f81e","runs":[{"text":"Know Before You Go: Laws & Money"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":158,"id":"79df7a3c-9403-53c2-8469-726deb5f960e","runs":[{"bold":true,"text":"Entry and paperwork"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":184,"id":"989cfc71-c753-5ad8-b682-2ed7f4cc317a","runs":[{"text":"US citizens can stay up to 90 days in any 180 in Germany and the Schengen area without a visa. Your passport must be under 10 years old and valid 3 months past departure. Since April 2026 the EU Entry/Exit System scans fingerprints and a photo instead of stamping passports."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":274,"id":"108a8e58-9501-5659-a824-d1d1f2e98922","runs":[{"bold":true,"text":"ETIAS not yet"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":300,"id":"52431f72-b658-5724-82ef-1ba6b23e5fda","runs":[{"text":"The EU travel authorization, ETIAS, is not running yet, so you do not need it for a trip in late 2026. A launch now looks likely in 2027, and the EU says it will give several months' notice."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":390,"id":"f73b9298-1d74-5785-b1f8-1c8c33f83296","runs":[{"bold":true,"text":"Cash still matters"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":416,"id":"eb0de297-83a8-51a5-87df-0e8b2e79ade4","runs":[{"text":"Germany uses the euro. Cards work in most places now, but small bakeries, sausage stands and some bars still take cash only, so carry 30 to 50 euros. Prices include VAT (19% on most goods). Ask for a tax-free form when you shop and get it stamped at customs before you fly home."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":506,"id":"b56cd8f1-6c4d-5428-8f63-12b08ccfc941","runs":[{"bold":true,"text":"Tickets and fines"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":532,"id":"e341f750-5932-52a2-9e7f-7b26f591f170","runs":[{"text":"Buy and validate your U-Bahn, S-Bahn, tram and bus ticket before you ride; plain-clothes inspectors fine riders without one 60 euros. An AB ticket covers central Berlin, and you need ABC for Potsdam. The Deutschlandticket, 63 euros a month in 2026, covers all local transport in Germany."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":622,"id":"7fd11e23-f7f5-51b9-b9e9-c843c3a31e0e","runs":[{"bold":true,"text":"Red lights and bike lanes"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":648,"id":"5f05fce1-ef68-51f1-9f6f-403e50e9ea5b","runs":[{"text":"Wait for the green walking man even if the street is empty; jaywalking can bring a fine and disapproving looks. Stay out of the red or marked bike lanes on sidewalks, because cyclists ride fast and expect them clear."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":9,"type":"information","title":"Know Before You Go: Customs","ink":"4E5A6E","elements":[{"x":56,"y":100,"id":"75dadb75-af71-520f-b68e-093547f000c3","runs":[{"text":"Know Before You Go: Customs"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":158,"id":"ff2de3a5-dfb7-54bf-b8d0-3991ac4cda76","runs":[{"bold":true,"text":"Sundays are quiet"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":184,"id":"496ed63a-e48b-5c5a-94f2-a1823b48e131","runs":[{"text":"Most shops and supermarkets close on Sundays and public holidays. Shops in big train stations stay open. Plan groceries for Saturday, and keep noise down on Sundays and after 10pm, called quiet time."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":274,"id":"4be18ac2-10bf-5b77-b8f9-d93a7d331d9c","runs":[{"bold":true,"text":"Tipping"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":300,"id":"ca326029-87f2-55ec-9f8e-78db0343731c","runs":[{"text":"Service is included, but rounding up or adding 5 to 10% is normal at a sit-down meal. Tell the server the total you want to pay as you hand over the money, rather than leaving coins on the table."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":390,"id":"6f24c3ca-f6c6-53e0-a104-21eb7f0ab166","runs":[{"bold":true,"text":"Pfand: bottle deposits"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":416,"id":"c6a33f2d-c486-5159-86e9-5f11e8e9e9fd","runs":[{"text":"Most bottles and cans carry a deposit of 8 to 25 cents. Return them to the machines in any supermarket for a receipt you can spend. Many Berliners leave empties beside public bins for collectors."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":506,"id":"f3c19aa5-0710-5898-b5b8-9f94c8618632","runs":[{"bold":true,"text":"Greetings and manners"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":532,"id":"f522bfae-7a7b-5664-98ae-2dcfd118fb73","runs":[{"text":"Say Guten Tag or Hallo when you walk into a small shop, and Tsch\u00fcss when you leave. Use Sie, the formal you, with strangers. Germans are direct and punctual; arrive on time for tours and reservations."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":622,"id":"3496a3e2-c6cc-52bc-be6e-a91d39883384","runs":[{"bold":true,"text":"History with care"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":648,"id":"d5d94891-669d-5f1e-a355-d4f976475dfa","runs":[{"text":"Nazi symbols and the Hitler salute are crimes in Germany, even as a joke. At memorials, be quiet and respectful; do not sit, climb or take playful photos at the Holocaust Memorial or the Wall Memorial."}],"type":"richtext","align":"left","color":"333333","width":500,"height":84,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":10,"type":"information","title":"German Phrases: The Basics","ink":"4E5A6E","elements":[{"x":56,"y":100,"id":"4b740088-29f0-5551-9adc-917a3f777f16","runs":[{"text":"German Phrases: The Basics"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":158,"id":"312ab3a0-45d7-5bea-9a8a-9d1455836255","runs":[{"bold":true,"text":"Hello and goodbye"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":184,"id":"c974f453-51e3-5346-a95f-36ffe234a9d8","runs":[{"text":"Hello:  "},{"bold":true,"text":"Hallo"},{"text":"  (HAH-loh)\n","italic":true},{"text":"Good day:  "},{"bold":true,"text":"Guten Tag"},{"text":"  (GOO-ten tahk)\n","italic":true},{"text":"Good evening:  "},{"bold":true,"text":"Guten Abend"},{"text":"  (GOO-ten AH-bent)\n","italic":true},{"text":"Bye:  "},{"bold":true,"text":"Tsch\u00fcss"},{"text":"  (chewss)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":263,"id":"ae52d6ab-c287-5103-a4fb-c3e1cbee3f39","runs":[{"bold":true,"text":"Polite words"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":289,"id":"a154ae6f-4506-5618-8710-d1e56197a7e5","runs":[{"text":"Please:  "},{"bold":true,"text":"Bitte"},{"text":"  (BIT-uh)\n","italic":true},{"text":"Thank you:  "},{"bold":true,"text":"Danke"},{"text":"  (DAHN-kuh)\n","italic":true},{"text":"You're welcome:  "},{"bold":true,"text":"Gern geschehen"},{"text":"  (gairn guh-SHAY-en)\n","italic":true},{"text":"Excuse me:  "},{"bold":true,"text":"Entschuldigung"},{"text":"  (ent-SHOOL-dee-goong)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":368,"id":"0bb580df-9f9a-5917-b15e-3ca71377fb6e","runs":[{"bold":true,"text":"When you're stuck"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":394,"id":"974e8a48-7a87-5e40-9f9d-2bb7869b950c","runs":[{"text":"Sorry:  "},{"bold":true,"text":"Es tut mir leid"},{"text":"  (es toot meer lite)\n","italic":true},{"text":"I don't understand:  "},{"bold":true,"text":"Ich verstehe nicht"},{"text":"  (ikh fer-SHTAY-uh nikht)\n","italic":true},{"text":"Do you speak English?:  "},{"bold":true,"text":"Sprechen Sie Englisch?"},{"text":"  (SHPREKH-en zee ENG-lish)\n","italic":true},{"text":"More slowly, please:  "},{"bold":true,"text":"Langsamer, bitte"},{"text":"  (LAHNG-zah-mer BIT-uh)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":473,"id":"696f46eb-2410-5f65-b94e-8e0bd360194a","runs":[{"bold":true,"text":"Small talk"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":499,"id":"22f66d4e-ff3c-5d58-9e8f-dc24fc9a00df","runs":[{"text":"Yes / No:  "},{"bold":true,"text":"Ja / Nein"},{"text":"  (yah / nine)\n","italic":true},{"text":"Fine, thanks:  "},{"bold":true,"text":"Gut, danke"},{"text":"  (goot DAHN-kuh)\n","italic":true},{"text":"Nice to meet you:  "},{"bold":true,"text":"Freut mich"},{"text":"  (froyt mikh)\n","italic":true},{"text":"See you later:  "},{"bold":true,"text":"Bis sp\u00e4ter"},{"text":"  (biss SHPAY-ter)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":578,"id":"c6e60acb-e8fe-5bbf-8189-24cc1381bcd6","runs":[{"bold":true,"text":"Numbers"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":604,"id":"eeed9a78-fecc-571c-932c-11e2a39b6a1d","runs":[{"text":"1 eins (ines) \u00b7 2 zwei (tsvy) \u00b7 3 drei (dry) \u00b7 4 vier (feer)\n"},{"text":"5 f\u00fcnf (fewnf) \u00b7 6 sechs (zeks) \u00b7 7 sieben (ZEE-ben)\n"},{"text":"8 acht (ahkht) \u00b7 9 neun (noyn) \u00b7 10 zehn (tsayn)\n"},{"text":"100 hundert (HOON-dert) \u00b7 1,000 tausend (TOW-zent) \u00b7 1,000,000 eine Million (INE-uh mil-YOHN)"}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"}]},{"n":11,"type":"information","title":"German Phrases: Out and About","ink":"4E5A6E","elements":[{"x":56,"y":100,"id":"ede863ad-e787-56f1-8080-3f4230de12cd","runs":[{"text":"German Phrases: Out and About"}],"type":"richtext","align":"center","color":"1E2A44","width":500,"height":44,"fontSize":28,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":158,"id":"88ee9be1-9b90-5824-beee-f4e7c95d202a","runs":[{"bold":true,"text":"Restroom and water"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":184,"id":"059cb0da-68a3-5142-a367-f05f4b98aff1","runs":[{"text":"Where is the restroom?:  "},{"bold":true,"text":"Wo ist die Toilette?"},{"text":"  (voh ist dee twah-LET-uh)\n","italic":true},{"text":"Men / Women:  "},{"bold":true,"text":"Herren / Damen"},{"text":"  (HAIR-en / DAH-men)\n","italic":true},{"text":"Tap water, please:  "},{"bold":true,"text":"Leitungswasser, bitte"},{"text":"  (LIE-toongs-vah-ser BIT-uh)\n","italic":true},{"text":"Still / sparkling:  "},{"bold":true,"text":"still / mit Kohlens\u00e4ure"},{"text":"  (shtill / mit KOH-len-zoy-ruh)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":263,"id":"63d9f80e-ac81-550e-8419-971f8722af07","runs":[{"bold":true,"text":"Eating out"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":289,"id":"68ea2b06-7c09-5080-ba6e-775e7df6ef69","runs":[{"text":"A table for two:  "},{"bold":true,"text":"Einen Tisch f\u00fcr zwei"},{"text":"  (INE-en tish fewr tsvy)\n","italic":true},{"text":"The menu, please:  "},{"bold":true,"text":"Die Speisekarte, bitte"},{"text":"  (dee SHPY-zuh-kar-tuh BIT-uh)\n","italic":true},{"text":"The bill, please:  "},{"bold":true,"text":"Die Rechnung, bitte"},{"text":"  (dee REKH-noong BIT-uh)\n","italic":true},{"text":"Cheers!:  "},{"bold":true,"text":"Prost!"},{"text":"  (prohst)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":368,"id":"ae64e322-ba8b-541f-a5b3-4d17039c3e9d","runs":[{"bold":true,"text":"Getting around"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":394,"id":"a7cfd1b6-10f2-5438-bb1d-8dd55e10cc7b","runs":[{"text":"Where is...?:  "},{"bold":true,"text":"Wo ist...?"},{"text":"  (voh ist)\n","italic":true},{"text":"The train station:  "},{"bold":true,"text":"Der Bahnhof"},{"text":"  (dair BAHN-hohf)\n","italic":true},{"text":"A ticket to...:  "},{"bold":true,"text":"Eine Fahrkarte nach..."},{"text":"  (INE-uh FAR-kar-tuh nahkh)\n","italic":true},{"text":"Left / Right / Straight:  "},{"bold":true,"text":"Links / Rechts / Geradeaus"},{"text":"  (links / rekhts / guh-RAH-duh-ows)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":473,"id":"1d83dc0a-2e2c-5aa9-a37e-3d9954e6b1e3","runs":[{"bold":true,"text":"Shopping"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":499,"id":"cfb3462c-c884-5f1e-b0de-b62f5b035f15","runs":[{"text":"How much is it?:  "},{"bold":true,"text":"Was kostet das?"},{"text":"  (vahs KOS-tet dahs)\n","italic":true},{"text":"Can I pay by card?:  "},{"bold":true,"text":"Kann ich mit Karte zahlen?"},{"text":"  (kahn ikh mit KAR-tuh TSAH-len)\n","italic":true},{"text":"Only cash?:  "},{"bold":true,"text":"Nur bar?"},{"text":"  (noor bar)\n","italic":true},{"text":"Just looking:  "},{"bold":true,"text":"Ich schaue nur"},{"text":"  (ikh SHOW-uh noor)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"},{"x":56,"y":578,"id":"3cd37293-7493-5f75-a8dc-d10f41740684","runs":[{"bold":true,"text":"Help"}],"type":"richtext","align":"left","color":"4E5A6E","width":500,"height":24,"fontSize":17,"rotation":0,"fontFamily":"Georgia, serif","fontWeight":"bold"},{"x":56,"y":604,"id":"f195ed67-b78c-5485-a189-9729d413711f","runs":[{"text":"Help!:  "},{"bold":true,"text":"Hilfe!"},{"text":"  (HIL-fuh)\n","italic":true},{"text":"I need a doctor:  "},{"bold":true,"text":"Ich brauche einen Arzt"},{"text":"  (ikh BROW-khuh INE-en artst)\n","italic":true},{"text":"Call the police:  "},{"bold":true,"text":"Rufen Sie die Polizei"},{"text":"  (ROO-fen zee dee poh-lee-TSY)\n","italic":true},{"text":"I am lost:  "},{"bold":true,"text":"Ich habe mich verlaufen"},{"text":"  (ikh HAH-buh mikh fer-LOW-fen)","italic":true}],"type":"richtext","align":"left","color":"333333","width":500,"height":67,"fontSize":12,"rotation":0,"fontFamily":"Georgia, serif"}]}]$J$; ns uuid:='3c0d1a2b-5e6f-4a7b-8c9d-0e1f2a3b4c55'; pid uuid;
begin
  pid:=extensions.uuid_generate_v5(ns,(d->>'code')||'/passport');
